function persist(){try{localStorage.setItem('es-saved',JSON.stringify(saved));localStorage.setItem('es-comp',JSON.stringify(comp))}catch(e){toast('Сохранение в браузере недоступно. Выбор сохранён до закрытия страницы.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function header(){const r=route();return `<header><div class="container header-inner"><a class="logo" href="#/" aria-label="EventSpace — главная"><i class="logo-mark"></i>Event<span>Space</span></a><span class="location">${ic('pin')}Минск</span><nav class="nav"><a class="${r==='/catalog'?'active':''}" href="#/catalog">Каталог площадок</a><a class="${r.startsWith('/cases')?'active':''}" href="#/cases">Кейсы мероприятий</a><a class="${r.startsWith('/journal')?'active':''}" href="#/journal">Журнал</a></nav><div class="header-actions"><a class="icon-btn compare-header" href="#/compare" aria-label="Сравнение">${ic('compare')}${comp.length?`<b class="count">${comp.length}</b>`:''}</a><a class="icon-btn" href="#/favorites" aria-label="Избранное">${ic('heart')}${saved.length?`<b class="count">${saved.length}</b>`:''}</a><a class="btn outline" href="#/owners">Разместить площадку ${ic('arrow')}</a><button class="icon-btn menu-btn" data-action="menu" aria-label="Открыть меню">${ic('menu')}</button></div></div></header>`}
function footer(){return `<footer><div class="container"><div class="footer-main"><div><a class="logo" href="#/"><i class="logo-mark"></i>Event<span>Space</span></a><p>Хорошие события начинаются<br>с подходящего места.</p><p style="margin-top:18px">Минск, Беларусь · BYN</p></div><div class="footer-col"><strong>Найти своё место</strong><a href="#/catalog">Каталог площадок</a><a href="#/cases">Кейсы мероприятий</a><a href="#/journal">Журнал</a><a href="#/favorites">Избранное</a><a href="#/compare">Сравнение</a></div><div class="footer-col"><strong>Владельцам</strong><a href="#/owners">Разместить площадку</a><a href="#/pricing">Тарифы и продвижение</a><a href="#/contacts">Сотрудничество</a></div><div class="footer-col"><strong>EventSpace</strong><a href="#/about">О проекте</a><a href="#/contacts">Контакты</a><a href="#/design">Дизайн-система</a><a href="#/states">Состояния интерфейса</a></div></div><div class="footer-bottom"><span>© 2026 EventSpace · Дизайн-прототип. Все предложения вымышлены.</span><a href="#/legal/privacy">Политика конфиденциальности</a><a href="#/legal/terms">Условия использования</a></div></div></footer>`}
function card(v){return `<article class="venue-card"><div class="card-photo"><a href="#/venue/${v.id}">${image(v.photo,v.name)}</a>${v.top?'<span class="badge ad">TOP · Реклама</span>':v.new?'<span class="badge">Новое место</span>':''}<button class="icon-btn ${saved.includes(v.id)?'selected':''}" data-action="favorite" data-id="${v.id}" aria-label="${saved.includes(v.id)?'Удалить из избранного':'Добавить в избранное'}" aria-pressed="${saved.includes(v.id)}">${ic('heart')}</button></div><div class="card-body"><a href="#/venue/${v.id}"><h3>${v.name}</h3></a><div class="card-sub">${ic('pin')}Минск · ${v.district} район</div><div class="card-tags"><span>${ic('guests')} до ${v.capacity} гостей</span><span>${v.type}</span><span>${v.features[0]}</span></div><div class="card-bottom"><span class="price">от ${v.price} <small>BYN / час</small></span><a class="card-link" href="#/venue/${v.id}">Подробнее ${ic('arrow')}</a></div><div class="card-links"><small style="color:var(--muted)">Минимум 3 часа</small><button class="compare-btn ${comp.includes(v.id)?'on':''}" data-action="compare" data-id="${v.id}" aria-pressed="${comp.includes(v.id)}">${ic(comp.includes(v.id)?'check':'compare')}${comp.includes(v.id)?'В сравнении':'Сравнить'}</button></div></div></article>`}
function caseCard(c){const v=venue(c.venue);return `<article class="case-card"><a href="#/cases/${c.id}"><div class="case-photo">${image(c.photo,c.name)}</div><span class="badge">${c.event} · ${c.guests} гостей</span><h3>${c.name}</h3></a><p>${v.name} · Иллюстративный кейс</p><a class="card-link" href="#/cases/${c.id}">Посмотреть кейс ${ic('arrow')}</a></article>`}
function articleCard(a){return `<article class="editor-card"><a href="#/journal/${a.id}">${image(a.photo,a.title)}<span class="eyebrow">${a.ad?'Реклама · ':''}${a.cat}</span><h3>${a.title}</h3><p>12 октября 2026 · ${a.time}</p></a></article>`}
function sectionHead(title,sub='',link='',label='Смотреть все'){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<a href="${link}">${label} ↗</a>`:''}</div>`}
function searchForm(){return `<form class="searchbox" id="home-search"><div class="searchfield"><label for="search-event">Ваше событие</label><select id="search-event" name="event"><option value="">Тип мероприятия</option>${categories.map(([c])=>`<option>${c}</option>`).join('')}</select></div><div class="searchfield"><label for="search-city">Где ищем</label><select id="search-city" name="district"><option value="">Минск и рядом</option>${['Центральный','Октябрьский','Советский','Московский','Минский район'].map(d=>`<option>${d}</option>`).join('')}</select></div><div class="searchfield"><label for="search-guests">Компания</label><input id="search-guests" name="guests" placeholder="Сколько гостей?" type="number" min="1" max="1000"></div><div class="searchfield"><label for="search-budget">Бюджет за час</label><select id="search-budget" name="price"><option value="500">Любой бюджет</option value="100">До 100 BYN</option value="200">До 200 BYN</option></select></div><button class="btn" type="submit">${ic('search')}Найти площадку</button></form>`}
function home(){return `<main><div class="container hero"><div class="hero-picture">${image('orangerie','Зелёная оранжерея, подготовленная к праздничному ужину')}<div class="hero-copy"><span class="eyebrow">МЕСТА, ГДЕ СЛУЧАЕТСЯ ВАЖНОЕ</span><h1>Ваше событие.<br><em>То самое место.</em></h1><p>Находите площадки в Минске, вдохновляйтесь событиями и связывайтесь с владельцами напрямую.</p></div><a class="photo-note" href="#/venue/oran"><span>Оранжерея «Сад» · Минск<br><small>Демонстрационная площадка</small></span><span class="icon-btn">${ic('arrow')}</span></a></div>${searchForm()}<div class="searchmeta"><span>Без регистрации · Прямые контакты владельцев</span><span>Вы выбираете место. Всё остальное — ваша история.</span></div></div><section class="section"><div class="container">${sectionHead('Для какого события ищем?')}<div class="categories">${categories.map(([c,i])=>`<a class="category" href="#/catalog?event=${encodeURIComponent(c)}">${ic(i)}<span>${c}</span><small>${venues.filter(v=>v.events.includes(c)).length} площадок</small></a>`).join('')}</div></div></section><section class="section soft"><div class="container">${sectionHead('Места, которые вдохновляют','Присмотритесь: возможно, ваше событие случится здесь.','#/catalog','Весь каталог')}<div class="grid3">${venues.slice(0,3).map(card).join('')}</div><p class="ad-label">TOP — рекламное размещение. Все площадки и цены в прототипе вымышлены.</p></div></section><section class="section"><div class="container">${sectionHead('Не просто место. Настроение.','Подборки для ваших больших и маленьких поводов.','#/journal','Все подборки')}<div class="grid2"><a class="collection" href="#/catalog?event=${encodeURIComponent('Свадьба')}">${image('orangerie','Праздничный ужин среди зелени')}<div class="collection-copy"><span class="eyebrow" style="color:#fff">БЛИЖЕ К ПРИРОДЕ</span><h3>Праздник с видом на зелень</h3><p>Оранжереи, террасы и загородные пространства ↗</p></div></a><a class="collection" href="#/catalog?type=${encodeURIComponent('Лофт')}">${image('studio','Атмосферный лофт для встреч')}<div class="collection-copy"><span class="eyebrow" style="color:#fff">СО СВОИМ ХАРАКТЕРОМ</span><h3>Места для смелых идей</h3><p>Лофты и пространства, которые легко сделать своими ↗</p></div></a></div></div></section><section class="section"><div class="container">${sectionHead('Новые знакомства','Пространства, которые недавно появились в каталоге.','#/catalog?sort=new','Посмотреть новые')}<div class="grid3">${venues.filter(v=>v.new).map(card).join('')}</div></div></section><section class="section soft"><div class="container">${sectionHead('Представьте, как это будет','Посмотрите, как пространство меняется вместе с событием.','#/cases','Все кейсы')}<div class="feature-story"><div class="story-copy"><span class="eyebrow">СВАДЬБА · 65 ГОСТЕЙ</span><h2>Ужин среди зелени<br>и самых близких</h2><p>Длинный стол, мягкий свет и ощущение, что весь мир может немного подождать.</p><small style="color:var(--muted)">Иллюстративный кейс · Оранжерея «Сад»</small>${btn('Посмотреть историю','#/cases/wedding','outline')}</div>${image('terrace','Иллюстрация камерной свадьбы')}</div></div></section><section class="section"><div class="container">${sectionHead('Журнал о хороших событиях','Идеи, полезные детали и немного вдохновения.','#/journal','Читать журнал')}<div class="grid3">${articles.slice(0,3).map(articleCard).join('')}</div></div></section><section class="section"><div class="container">${sectionHead('От идеи — к своему месту')}<div class="steps"><div><span class="step-num">01</span><h3>Расскажите о событии</h3><p>Выберите формат, число гостей и комфортный бюджет.</p></div><div><span class="step-num">02</span><h3>Найдите своих фаворитов</h3><p>Посмотрите фотографии, сохраните и сравните площадки.</p></div><div><span class="step-num">03</span><h3>Свяжитесь напрямую</h3><p>Обсудите детали с владельцем. Договорённости — между вами.</p></div></div></div></section><div class="container"><div class="owner-banner"><div><span class="eyebrow" style="color:#d9c7a5">ДЛЯ ВЛАДЕЛЬЦЕВ ПРОСТРАНСТВ</span><h2>У вашего места есть история.<br>Поможем её рассказать.</h2><p>Разместите площадку бесплатно и познакомьте с ней людей, которые планируют своё событие.</p></div>${btn('Разместить площадку','#/owners','peach')}</div></div></main>`}
function pageTop(title,description='',crumb=''){return `<div class="page-top"><div class="breadcrumbs"><a href="#/">Главная</a><span>/</span>${crumb||title}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`}
function filterPanel(scope=''){const checkGroup=(title,vals,key)=>`<div class="filter-group"><label class="title">${title}</label>${vals.map(f=>`<label class="check"><input type="checkbox" data-filter="${key}" value="${f}" ${filters.features.includes(f)?'checked':''}>${f}</label>`).join('')}</div>`;return `<aside class="filter-panel"><div style="display:flex;justify-content:space-between;align-items:center"><h3>Фильтры</h3><button class="text-btn" data-action="reset-filters" style="font-size:11px">Сбросить</button></div><div class="filter-group"><label class="title" for="district-filter${scope}">Город и район</label><select class="input" id="district-filter${scope}" data-filter="district"><option value="">Минск и рядом</option>${['Центральный','Октябрьский','Советский','Московский','Минский район'].map(x=>`<option ${filters.district===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="filter-group"><label class="title" for="event-filter${scope}">Тип мероприятия</label><select class="input" id="event-filter${scope}" data-filter="event"><option value="">Любое событие</option>${categories.map(([c])=>`<option ${filters.event===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="filter-group"><label class="title" for="type-filter${scope}">Тип площадки</label><select class="input" id="type-filter${scope}" data-filter="type"><option value="">Любая площадка</option>${[...new Set(venues.map(v=>v.type))].map(x=>`<option ${filters.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="filter-group"><label class="title" for="guest-filter${scope}">Количество гостей</label><input class="input" id="guest-filter${scope}" data-filter="guests" type="number" min="1" max="1000" placeholder="Например, 60" value="${filters.guests}"></div><div class="filter-group"><label class="title" for="price-filter${scope}">Цена за час: до ${filters.price} BYN</label><input class="range" id="price-filter${scope}" aria-label="Максимальная цена за час" data-filter="price" type="range" min="50" max="500" step="10" value="${filters.price}"><small style="color:var(--muted)">50 BYN — 500 BYN</small></div>${checkGroup('Оборудование',['Проектор','Звуковая система','Сцена'],'features')}${checkGroup('Ваши условия',['Свой алкоголь','Свой кейтеринг'],'features')}${checkGroup('Удобства',['Парковка','Wi-Fi','Терраса','Доступная среда'],'features')}<button class="btn full filter-apply" data-action="close-filters">Показать площадки</button></aside>`}
function filteredVenues(){let v=venues.filter(v=>(!filters.q||(v.name+' '+v.type).toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.event||v.events.includes(filters.event))&&(!filters.district||v.district===filters.district)&&(!filters.type||v.type===filters.type)&&(!filters.guests||v.capacity>=Number(filters.guests))&&v.price<=Number(filters.price)&&filters.features.every(f=>v.features.includes(f)));if(sort==='cheap')v.sort((a,b)=>a.price-b.price);if(sort==='expensive')v.sort((a,b)=>b.price-a.price);if(sort==='capacity')v.sort((a,b)=>b.capacity-a.capacity);if(sort==='new')v.sort((a,b)=>Number(!!b.new)-Number(!!a.new));return v}
function activeChips(){let r=[];for(const k of ['event','district','type','guests'])if(filters[k])r.push(`<button class="chip active" data-action="remove-filter" data-key="${k}">${k==='guests'?'От '+filters[k]+' гостей':esc(filters[k])}${ic('close')}</button>`);if(filters.price<500)r.push(`<button class="chip active" data-action="remove-filter" data-key="price">До ${filters.price} BYN${ic('close')}</button>`);filters.features.forEach(f=>r.push(`<button class="chip active" data-action="remove-feature" data-id="${f}">${f}${ic('close')}</button>`));return r.join('')}
function mapMarkup(vs){return `<div class="map"><svg class="map-art" viewBox="0 0 800 450" preserveAspectRatio="none" aria-hidden="true"><rect width="800" height="450" fill="#e9ecdf"/><path d="M-30 350 250 290 430 160 750 100 840 130" fill="none" stroke="#c1d1cc" stroke-width="38"/><path d="M100-10 170 160 350 220 550 450M0 100 190 170 390 100 800 300M10 430 210 360 490 340 800 370M400-20 360 170 260 460M650-10 620 190 730 450" stroke="#fafbf6" stroke-width="18" fill="none"/><path d="M100-10 170 160 350 220 550 450M0 100 190 170 390 100 800 300" stroke="#d5d9cc" stroke-width="1" fill="none"/><text x="360" y="260" font-family="Arial" font-size="24" fill="#98a28f">МИНСК</text><circle cx="70" cy="260" r="45" fill="#d6dfc6"/><circle cx="700" cy="50" r="70" fill="#d6dfc6"/></svg>${vs.map((v,i)=>`<button class="map-pin" style="left:${12+(i*19)%68}%;top:${18+(i*17)%60}%" data-action="map-preview" data-id="${v.id}">${v.price} BYN</button>`).join('')}<span class="map-caption">Схема расположения · условные адреса, не для навигации</span><div id="map-preview"></div></div>`}
function catalog(){const vs=filteredVenues();return `<main class="container">${pageTop('Место для вашего события','От камерного ужина до большой конференции — найдите пространство по своему настроению.','Каталог площадок')}<div class="toolbar"><input class="input" id="catalog-query" placeholder="Поиск по названию или типу" aria-label="Поиск площадок" value="${esc(filters.q)}"><button class="btn outline mobile-filter" data-action="filters">${ic('filter')}Фильтры</button><select class="input sort" id="sort" aria-label="Сортировка">${[['recommended','Рекомендуемые'],['cheap','Сначала дешевле'],['expensive','Сначала дороже'],['capacity','Больше вместимость'],['new','Сначала новые']].map(([val,t])=>`<option value="${val}" ${sort===val?'selected':''}>${t}</option>`).join('')}</select><div class="segmented"><button class="${!mapView?'active':''}" data-action="view-list">${ic('grid')}<span>Список</span></button><button class="${mapView?'active':''}" data-action="view-map">${ic('pin')}<span>Карта</span></button></div></div><div class="catalog-layout">${filterPanel()}<div class="catalog-results"><div class="chips">${activeChips()}</div><div class="result-count">Найдено площадок: <strong>${vs.length}</strong> · цены в BYN за час · демонстрационные предложения</div>${vs.length?(mapView?mapMarkup(vs):`<div class="grid3">${vs.slice(0,showCount).map(card).join('')}</div>${showCount<vs.length?`<div class="pagination"><button class="btn light" style="width:auto" data-action="load-more">Показать ещё ${vs.length-showCount}</button></div>`:''}`):empty('search','Здесь пока тихо','Попробуйте расширить район, увеличить бюджет или убрать часть фильтров.','Сбросить фильтры','reset-filters')}</div></div></main>`}
function empty(icon,title,text,action,handler,url){return `<div class="empty"><span class="empty-symbol">${ic(icon)}</span><h2>${title}</h2><p>${text}</p>${url?btn(action,url):`<button class="btn" data-action="${handler}">${action}${ic('arrow')}</button>`}</div>`}
function contactBlock(v){return `<div class="contact-card"><span class="eyebrow">АРЕНДА ПРОСТРАНСТВА</span><div class="price">от ${v.price} <small>BYN / час</small></div><p>Минимальная аренда — 3 часа.<br>Итоговую стоимость уточняйте у владельца.</p><button class="btn full" data-action="contact" data-id="${v.id}">${ic('phone')}Связаться с площадкой</button><button class="btn light full" data-action="contact-channel" data-channel="Telegram">${ic('send')}Написать в Telegram</button><button class="text-btn" data-action="contact-channel" data-channel="Сайт площадки" style="width:100%;justify-content:center">${ic('web')}Сайт площадки ↗</button><div class="contact-person"><span class="avatar">А</span><div>Анна · представитель<br><small style="color:var(--muted)">Демонстрационный контакт</small></div></div><small style="color:var(--muted);display:block;font-size:10px">Условия и доступность обсуждаются напрямую с владельцем.</small></div>`}
function galleryFor(v){return [v.photo,'terrace','hall','dinner',v.photo]}
function venuePage(id){const v=venues.find(v=>v.id===id);if(!v)return notFound();return `<main class="detail-page"><div class="container"><div class="page-top"><div class="breadcrumbs"><a href="#/">Главная</a> / <a href="#/catalog">Площадки</a> / ${v.name}</div><div class="title-row"><h1>${v.name}</h1><div class="title-actions"><button class="icon-btn ${saved.includes(v.id)?'selected':''}" data-action="favorite" data-id="${v.id}" aria-label="Добавить в избранное" aria-pressed="${saved.includes(v.id)}">${ic('heart')}</button><button class="icon-btn" data-action="compare" data-id="${v.id}" aria-label="Сравнить площадку">${ic('compare')}</button></div></div><p style="font-size:12px">${ic('pin')} ${v.address} ${v.top?' · <span class="badge ad">TOP · Реклама</span>':''}</p></div><div class="gallery">${galleryFor(v).map((im,i)=>`<button data-action="gallery" data-id="${v.id}" data-index="${i}" aria-label="Открыть фото ${i+1}">${image(im,v.name+' · фото '+(i+1))}</button>`).join('')}<button class="gallery-all" data-action="gallery" data-id="${v.id}" data-index="0">${ic('grid')}Все 5 фото</button></div><div class="detail-layout"><div class="detail-content"><div class="facts"><div><strong>до ${v.capacity}</strong><small>гостей</small></div><div><strong>${v.area} м²</strong><small>площадь</small></div><div><strong>${v.type}</strong><small>тип пространства</small></div></div><section><h2>Место, где всё сложится</h2><p>${v.desc||'Универсальное пространство для встреч, которые хочется запомнить. Продуманная планировка, внимательное отношение к деталям и возможность адаптировать зал под ваш формат.'}</p><p style="margin-top:14px">Здесь можно устроить ${v.events.map(x=>x.toLowerCase()).join(', ')}. Зоны для гостей и оборудования настраиваются под формат события. Перед выбором рекомендуем посетить площадку и обсудить детали с представителем.</p><div class="card-tags" style="margin-top:20px;margin-bottom:0">${v.events.map(x=>`<span>${x}</span>`).join('')}</div></section><section><h2>Что есть на площадке</h2><p class="amenities-hint">Наведите на пункт или нажмите, чтобы узнать подробности.</p><div class="amenities amenities-interactive">${[...v.features,'Мебель для гостей','Естественное освещение'].map((f,i)=>amenityItem(v,f,i)).join('')}</div></section><section><h2>Полезно знать</h2><div class="amenities"><div>${ic('check')}Аренда от 3 часов</div><div>${ic('check')}Монтаж по договорённости</div><div>${ic('info')}Курение только на улице</div><div>${ic('info')}Музыка до 23:00</div></div><p style="margin-top:20px">Условия по кейтерингу, алкоголю, уборке и времени подготовки согласуйте с владельцем. Доступность конкретной даты уточняется напрямую.</p></section><section><h2>Как добраться</h2><p style="margin-bottom:18px">${v.address}</p>${mapMarkup([v])}</section><section><h2>События в этом пространстве</h2><p style="margin-bottom:23px">Иллюстративные примеры оформления и использования площадки.</p><div class="grid2">${cases.filter(c=>c.venue===v.id).map(caseCard).join('')||'<p>Для этой площадки пока нет иллюстративных кейсов.</p>'}</div></section></div>${contactBlock(v)}</div><div style="margin-top:28px">${demo}</div><section class="section">${sectionHead('Похожие по настроению','','#/catalog','Весь каталог')}<div class="grid3">${venues.filter(x=>x.id!==v.id).slice(0,3).map(card).join('')}</div></section></div><div class="mobile-contact"><span class="price">от ${v.price} <small>BYN / час</small></span><button class="btn" data-action="contact" data-id="${v.id}">${ic('phone')}Связаться с площадкой</button></div></main>`}
const amenityDetails={
  'Парковка':v=>`На территории — ${v.capacity>=150?30:18} парковочных мест. Есть зона для краткой остановки и разгрузки оборудования. Места для гостей согласуйте заранее.`,
  'Проектор':v=>v.id==='forum'?'Лазерный проектор Full HD, яркость 5 000 лм, экран шириной 4 м. Подключение по HDMI; переходник USB-C предоставляется. Настройка с техником по договорённости.':'Проектор Full HD (1920 × 1080), яркость 4 000 лм и экран 3 × 2 м. Подключение по HDMI, переходник USB-C предоставляется. Входит в аренду.',
  'Звуковая система':v=>v.id==='oran'?'Две активные акустические колонки, микшер и два беспроводных микрофона. Подключение ноутбука по кабелю. Базовый комплект входит в аренду; работа звукорежиссёра обсуждается отдельно.':'Две активные акустические колонки, микшерный пульт и два беспроводных микрофона. Есть линейный вход для ноутбука или DJ-пульта. Состав комплекта и техническое сопровождение согласуйте с представителем.',
  'Сцена':v=>`Модульный подиум ${v.capacity>=150?'6 × 4':'4 × 3'} м, высота 40 см. Расстановка и время монтажа согласуются заранее. Дополнительное сценическое освещение — по запросу.`,
  'Свой алкоголь':()=> 'Можно привезти свои напитки. Условия пробкового сбора, наличие бокалов и обслуживание уточняются при обсуждении мероприятия.',
  'Свой кейтеринг':()=> 'Можно пригласить свою кейтеринговую команду. Есть зона для подготовки и подключения оборудования. Время заезда, уборка и доступ к кухне согласуются заранее.',
  'Wi-Fi':()=> 'Отдельная гостевая сеть доступна в основном зале. Для видеотрансляции или большого числа подключений заранее уточните пропускную способность и возможность проводного подключения.',
  'Терраса':()=> 'Открытая зона со столиками и местами для отдыха. Может использоваться для приветственного фуршета или церемонии. Работа зависит от погоды; обогрев и навес уточняются отдельно.',
  'Доступная среда':()=> 'Предусмотрен вход без ступеней и широкий проход в основной зал. Наличие доступного санузла и удобного маршрута от парковки уточните у представителя перед визитом.',
  'Мебель для гостей':v=>`Столы и стулья для рассадки до ${v.capacity} гостей. Возможны банкетная, театральная и свободная схемы. Текстиль, декор и нестандартная мебель обсуждаются отдельно.`,
  'Естественное освещение':()=> 'В основном зале есть большие окна и дневной свет. Интенсивность зависит от времени суток и погоды. Для проекции и съёмки уточните возможность затемнения.'
};
function amenityItem(v,label,index){const id=`amenity-${v.id}-${index}`;const description=amenityDetails[label]?.(v)||'Подробности и условия использования уточните у представителя площадки.';const icon=label==='Мебель для гостей'?'guests':label==='Естественное освещение'?'leaf':featureIcon(label);return `<div class="amenity-item"><button type="button" class="amenity-trigger" data-action="amenity-info" aria-expanded="false" aria-controls="${id}" aria-describedby="${id}">${ic(icon)}<span>${esc(label)}</span>${ic('info','amenity-info-icon')}</button><span class="amenity-tip" id="${id}" role="tooltip" hidden><strong>${esc(label)}</strong><span>${esc(description)}</span><small>Демонстрационные сведения</small></span></div>`}
let amenityOpen=null,amenityCloseTimer;
function closeAmenity(){clearTimeout(amenityCloseTimer);if(!amenityOpen)return;amenityOpen.tip.hidden=true;amenityOpen.trigger.setAttribute('aria-expanded','false');amenityOpen=null}
function positionAmenity(trigger,tip){const rect=trigger.getBoundingClientRect(),box=tip.getBoundingClientRect(),gap=8,edge=12;const viewportWidth=document.documentElement.clientWidth,viewportHeight=window.innerHeight;tip.style.left=Math.max(edge,Math.min(rect.left,viewportWidth-box.width-edge))+'px';let top=rect.bottom+gap;if(top+box.height>viewportHeight-edge)top=rect.top-box.height-gap;tip.style.top=Math.max(edge,Math.min(top,viewportHeight-box.height-edge))+'px'}
function showAmenity(trigger,pinned=false){clearTimeout(amenityCloseTimer);if(amenityOpen?.trigger===trigger){amenityOpen.pinned=amenityOpen.pinned||pinned;return}closeAmenity();const tip=document.getElementById(trigger.getAttribute('aria-controls'));if(!tip)return;tip.hidden=false;trigger.setAttribute('aria-expanded','true');amenityOpen={trigger,tip,pinned};positionAmenity(trigger,tip)}
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const item=e.target.closest('.amenity-item');if(!item)return;clearTimeout(amenityCloseTimer);if(!item.contains(e.relatedTarget))showAmenity(item.querySelector('.amenity-trigger'))});
document.addEventListener('pointerout',e=>{const item=e.target.closest('.amenity-item');if(!item||item.contains(e.relatedTarget)||!amenityOpen||amenityOpen.pinned)return;if(amenityOpen.trigger===document.activeElement&&amenityOpen.trigger.matches(':focus-visible'))return;amenityCloseTimer=setTimeout(closeAmenity,160)});
document.addEventListener('focusin',e=>{if(e.target.matches('.amenity-trigger:focus-visible'))showAmenity(e.target)});
document.addEventListener('focusout',e=>{if(amenityOpen?.trigger===e.target&&!e.target.closest('.amenity-item').contains(e.relatedTarget))closeAmenity()});
document.addEventListener('pointerdown',e=>{if(amenityOpen&&!amenityOpen.trigger.closest('.amenity-item').contains(e.target))closeAmenity()});
window.addEventListener('resize',closeAmenity);window.addEventListener('scroll',closeAmenity,{passive:true});
function featureIcon(f){return {'Парковка':'parking','Проектор':'screen','Звуковая система':'sound','Свой алкоголь':'wine','Свой кейтеринг':'food','Wi-Fi':'wifi','Терраса':'leaf','Сцена':'conference','Доступная среда':'guests'}[f]||'check'}
function comparePage(){const vs=comp.map(venue);const rows=[['Район',v=>v.district],['Стоимость',v=>`от ${v.price} BYN / час`],['Вместимость',v=>`до ${v.capacity} гостей`],['Тип помещения',v=>v.type],['Площадь',v=>`${v.area} м²`],['Парковка',v=>v.features.includes('Парковка')?'Есть':'Нет'],['Оборудование',v=>v.features.filter(f=>['Проектор','Звуковая система','Сцена'].includes(f)).join(', ')||'Не указано'],['Свой алкоголь',v=>v.features.includes('Свой алкоголь')?'Можно':'По согласованию'],['Свой кейтеринг',v=>v.features.includes('Свой кейтеринг')?'Можно':'Кейтеринг площадки'],['Удобства',v=>v.features.filter(f=>['Wi-Fi','Терраса','Доступная среда'].includes(f)).join(', ')||'Не указано'],['Кейсы',v=>v.cases+' кейс(ов) в прототипе']];return `<main class="container">${pageTop('Сравните и почувствуйте разницу','Все важные детали рядом. Можно сравнить от двух до четырёх площадок.','Сравнение')}${!vs.length?empty('compare','Сначала — ваши фавориты','Нажмите «Сравнить» на карточке площадки в каталоге. Выберите от двух до четырёх мест.','Выбрать площадки',null,'#/catalog'):`<div class="toolbar"><label class="check"><input class="toggle" id="differences" type="checkbox" ${differences?'checked':''}>Показать только различия</label><span style="font-size:12px;color:var(--muted)">${vs.length} из 4 площадок</span><button class="text-btn" style="margin-left:auto" data-action="clear-compare">Очистить список</button></div>${vs.length===1?'<p class="demo-note" style="margin-bottom:20px">Добавьте ещё одну площадку для сравнения.</p>':''}<div class="compare-scroll"><table class="compare-table"><thead><tr><th>Ваши варианты<br><small>На телефоне прокрутите таблицу влево и вправо.</small>${vs.length<4?`<p style="margin-top:20px">${btn('Добавить','#/catalog','outline small')}</p>`:''}</th>${vs.map(v=>`<th>${image(v.photo,v.name)}<div class="remove-compare"><h3><a href="#/venue/${v.id}">${v.name}</a></h3><button class="text-btn" data-action="compare" data-id="${v.id}" aria-label="Убрать ${v.name}">${ic('close')}</button></div><div class="button-row">${btn('Подробнее',`#/venue/${v.id}`,'outline small')}<button class="btn small" data-action="contact" data-id="${v.id}">Связаться</button></div></th>`).join('')}</tr></thead><tbody>${rows.filter(([l,f])=>!differences||new Set(vs.map(f)).size>1).map(([l,f])=>`<tr><td>${l}</td>${vs.map(v=>`<td class="${new Set(vs.map(f)).size>1?'diff':''}">${f(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="spacer"></div>${demo}`}</main>`}
function favorites(){return `<main class="container">${pageTop('Места, к которым хочется вернуться','Сохраняйте понравившееся и выбирайте без спешки. Регистрация не нужна.','Избранное')}${saved.length?`<div class="toolbar"><p>Сохранено площадок: ${saved.length}</p><button class="text-btn" style="margin-left:auto" data-action="clear-favorites">Удалить все</button></div><div class="grid3">${saved.map(id=>card(venue(id))).join('')}</div><p style="font-size:11px;margin-top:25px">Избранное сохраняется в этом браузере.</p>`:empty('heart','Ваше место ещё впереди','Сохраняйте площадки с помощью сердечка. Они будут ждать вас здесь, в этом браузере.','Открыть каталог',null,'#/catalog')}</main>`}
function casesPage(){let cs=cases.filter(c=>(!caseFilter||c.event===caseFilter)&&(!caseGuests||(caseGuests==='small'?c.guests<=50:c.guests>50)));return `<main class="container">${pageTop('Так выглядят хорошие события','Вдохновляйтесь историями и смотрите, как пространство становится частью праздника.','Кейсы мероприятий')}<div class="chips">${['',...categories.map(x=>x[0])].map(x=>`<button class="chip ${caseFilter===x?'active':''}" data-action="case-filter" data-id="${x}">${x||'Все события'}</button>`).join('')}</div><div class="toolbar"><select class="input" id="case-guests" aria-label="Количество гостей"><option value="">Любое количество гостей</option value="small" ${caseGuests==='small'?'selected':''}>До 50 гостей</option><option value="large" ${caseGuests==='large'?'selected':''}>Больше 50 гостей</option></select><span class="demo-note">Иллюстративные истории и фотографии · не реальные мероприятия</span></div>${cs.length?`<div class="grid2">${cs.map(caseCard).join('')}</div>`:empty('camera','История ещё не написана','Для этого сочетания фильтров пока нет кейсов. Посмотрите другие форматы.','Все события','reset-cases')}</main>`}
function casePage(id){const c=cases.find(x=>x.id===id);if(!c)return notFound();const v=venue(c.venue);return `<main class="container">${pageTop(c.name,'',`<a href="#/cases">Кейсы мероприятий</a> / ${c.name}`)}<div class="case-meta"><span>${c.event}</span><span>${c.guests} гостей</span><a href="#/venue/${v.id}">${ic('pin')} ${v.name} ↗</a><span class="badge">Иллюстративный кейс</span></div><div class="wide-photo">${image(c.photo,c.name)}</div><section class="section"><div class="reading"><span class="eyebrow">ИСТОРИЯ СОБЫТИЯ</span><h2>Когда место становится частью истории</h2><p class="intro" style="margin-top:25px">${c.desc}</p><h2>Пространство и детали</h2><p>Центром композиции стала общая зона для гостей. Декор выбрали спокойный: натуральный текстиль, небольшие цветочные композиции и тёплое освещение. Проходы оставили свободными, чтобы гостям и команде было удобно перемещаться.</p><div class="photo-grid">${image('dinner','Иллюстрация сервировки стола')}${image('hall','Иллюстрация оформления пространства')}</div><h2>Что помогло воплотить идею</h2><div class="amenities"><div>${ic('sound')}Звуковая система</div><div>${ic('screen')}Проектор для истории</div><div>${ic('guests')}Мобильная мебель</div><div>${ic('spark')}Дополнительный свет</div></div><blockquote>«Оставьте в пространстве место для общения — именно его гости запомнят лучше всего».</blockquote><small style="color:var(--muted)">Редакционная заметка для демонстрационного кейса.</small><div class="inline-venue">${image(v.photo,v.name)}<div><span class="eyebrow">МЕСТО ЭТОЙ ИСТОРИИ</span><h3>${v.name}</h3><p style="font-size:12px">До ${v.capacity} гостей · от ${v.price} BYN / час</p>${btn('Посмотреть площадку',`#/venue/${v.id}`,'small')}</div></div>${demo}</div></section><section class="section">${sectionHead('Другие истории','','#/cases','Все кейсы')}<div class="grid3">${cases.filter(x=>x.id!==id).slice(0,3).map(caseCard).join('')}</div></section></main>`}
function journal(){const as=articles.filter(a=>(!journalFilter||a.cat===journalFilter)&&(!journalQuery||a.title.toLowerCase().includes(journalQuery.toLowerCase())));return `<main class="container">${pageTop('Журнал EventSpace','О местах, людях и событиях, ради которых стоит собраться.','Журнал')}<div class="toolbar"><div class="chips" style="margin:0">${['','Подборки площадок','Идеи мероприятий','Советы','Новости','Партнёрские материалы'].map(c=>`<button class="chip ${journalFilter===c?'active':''}" data-action="journal-filter" data-id="${c}">${c||'Все материалы'}</button>`).join('')}</div><input class="input" id="journal-query" value="${esc(journalQuery)}" placeholder="Найти в журнале" aria-label="Поиск по журналу"></div>${as.length?`${!journalFilter&&!journalQuery?`<a class="journal-hero" href="#/journal/choose">${image('orangerie',articles[0].title)}<div><span class="eyebrow">ВЫБОР РЕДАКЦИИ · СОВЕТЫ</span><h2>${articles[0].title}</h2><p>От первого впечатления до практичных деталей. На что смотреть, чтобы найти своё пространство.</p><span class="card-link">Читать материал ${ic('arrow')}</span><p style="font-size:11px;margin-top:25px">Редакция EventSpace · 12 октября 2026 · 7 минут</p></div></a>`:''}<div class="grid3">${(!journalFilter&&!journalQuery?as.slice(1):as).map(articleCard).join('')}</div>`:empty('search','Такого материала пока нет','Попробуйте другой запрос или откройте все материалы.','Все материалы','reset-journal')}<section class="section"><div class="feature-story"><div class="story-copy"><span class="eyebrow">ЧАЩЕ ЧИТАЮТ</span><h2>Сначала — правильные вопросы</h2><p>Небольшой список, который поможет подготовиться к разговору с владельцем.</p>${btn('12 вопросов о площадке','#/journal/checklist','outline')}</div>${image('studio','Светлое пространство для встреч')}</div></section><span class="demo-note">Демонстрационные редакционные материалы · иллюстративные фотографии</span></main>`}
function articlePage(id){const a=articles.find(x=>x.id===id);if(!a)return notFound();return `<main class="container"><div class="page-top"><div class="breadcrumbs"><a href="#/">Главная</a> / <a href="#/journal">Журнал</a> / ${a.cat}</div></div><div class="reading"><span class="eyebrow">${a.ad?'РЕКЛАМА · ПАРТНЁРСКИЙ МАТЕРИАЛ':a.cat}</span><h1>${a.title}</h1><div class="case-meta"><span>Редакция EventSpace</span><span>12 октября 2026</span><span>${a.time} чтения</span></div>${a.ad?'<div class="demo-note" style="margin-bottom:20px">Реклама · демонстрационный партнёр «Мануфактура». Реквизиты рекламодателя добавляются до публикации.</div>':''}</div><div class="wide-photo">${image(a.photo,a.title)}</div><section class="section"><article class="reading"><p class="intro">${a.intro||'У каждого пространства свой характер. Рассказываем, как заметить нужные детали и превратить идею в событие, которое будет приятно вспоминать.'}</p><h2>Начните не с адреса, а с ощущения</h2><p>Представьте вечер: кто рядом с вами, как звучит музыка, сидят ли гости за одним столом или свободно перемещаются по залу. Ответы помогут понять, какое пространство искать — светлую студию, уютную гостиную или большой зал со сценой.</p><p>Затем определите три опоры: формат мероприятия, примерное количество гостей и бюджет на аренду. Так вы сможете сравнивать площадки по одинаковым условиям.</p><h2>Посмотрите, как живёт пространство</h2><p>Фотографии пустого зала показывают архитектуру. Кейсы помогают увидеть масштаб, расстановку столов и реальное количество свободного места. Обратите внимание на проходы, дневное освещение и зоны для отдыха.</p><blockquote>Хорошая площадка помогает вашей идее стать яснее.</blockquote><div class="photo-grid">${image('garden','Пример торжественного оформления')}${image('dinner','Пример камерной сервировки')}</div><h2>Проверьте практичные детали</h2><p>Уточните, что входит в стоимость: мебель, оборудование, уборка, часы монтажа и демонтажа. Обсудите собственный кейтеринг, алкоголь и ограничения по шуму. Попросите показать зону разгрузки и вход для гостей.</p><div class="amenities"><div>${ic('check')}Итоговая стоимость</div><div>${ic('check')}Время подготовки</div><div>${ic('check')}Оборудование и мебель</div><div>${ic('check')}Правила и ограничения</div></div><h2>Место, с которого можно начать</h2><p>В каталоге удобно сохранить несколько вариантов и сравнить их по вместимости, цене и условиям. Например, вот пространство из нашей демонстрационной подборки.</p><div class="inline-venue">${image('orangerie','Оранжерея «Сад»')}<div><span class="eyebrow">СВЯЗАННАЯ ПЛОЩАДКА</span><h3>Оранжерея «Сад»</h3><p style="font-size:12px">До 120 гостей · от 150 BYN / час</p>${btn('Посмотреть','#/venue/oran','small')}</div></div><h2>И обязательно познакомьтесь лично</h2><p>Перед окончательным решением договоритесь о просмотре. Почувствуйте акустику, оцените свет и задайте владельцу оставшиеся вопросы. В EventSpace вы связываетесь с представителем напрямую и самостоятельно согласовываете условия.</p>${demo}<div style="margin-top:30px"><a class="card-link" href="#/journal">${ic('back')}Назад в журнал</a></div></article></section><section class="section">${sectionHead('Продолжить чтение')}<div class="grid3">${articles.filter(x=>x.id!==id).slice(0,3).map(articleCard).join('')}</div></section></main>`}
const planData=[{name:'FREE',price:0,tag:'Первое знакомство',desc:'Чтобы ваше пространство нашли',features:['До 5 фотографий','Краткое описание','Контакты и характеристики','1 кейс','Базовая статистика']},{name:'PRO',price:39,tag:'Больше возможностей',desc:'Чтобы рассказать о себе подробнее',features:['До 30 фотографий и видео','Подробное описание','До 5 кейсов','Специальные предложения','Расширенная аналитика','Дополнительное оформление']},{name:'TOP',price:99,tag:'Больше внимания',desc:'Чтобы быть заметнее в каталоге',features:['Всё из PRO','До 10 кейсов','Рекламное продвижение','Приоритетные рекламные позиции','Визуальное выделение','Рекламная статистика']}];
function plans(){return `<div class="plans">${planData.map((p,i)=>`<article class="plan ${i===1?'featured':''}">${i===1?'<span class="badge">Больше возможностей</span>':''}<span class="eyebrow" style="color:inherit">${p.name}</span><h3>${p.tag}</h3><div class="plan-price">${p.price}<small> BYN / мес.</small></div><p>${p.desc}</p><ul>${p.features.map(f=>`<li>${ic('check')}${f}</li>`).join('')}</ul><a class="btn full ${i===1?'peach':'outline'}" href="#/owners?plan=${p.name}">${i?'Выбрать '+p.name:'Начать бесплатно'}${ic('arrow')}</a></article>`).join('')}</div><p class="ad-label" style="margin-top:20px">Цены демонстрационные до окончательного утверждения. TOP-размещения явно помечаются как реклама.</p>`}
const faqs=[['Нужно ли регистрироваться для поиска?','Нет. Каталог, контакты, сравнение и избранное доступны без регистрации. Избранное и сравнение сохраняются в вашем браузере.'],['Можно ли забронировать площадку через EventSpace?','Вы выбираете площадку и связываетесь с владельцем напрямую. Доступность, условия аренды и расчёты обсуждаются с ним.'],['Как разместить свою площадку?','Оставьте короткую заявку. В рабочей версии сервиса команда свяжется с вами и поможет подготовить карточку. В этом прототипе форма только демонстрирует сценарий.'],['Можно ли начать бесплатно?','Да, для этого предусмотрен тариф FREE. Он включает основные сведения, контакты, до пяти фотографий и один кейс.'],['Что даёт рекламное продвижение?','Тариф TOP предусматривает рекламные позиции и визуальное выделение в каталоге. Такие карточки получают явную метку «TOP · Реклама».'],['Как изменить тариф?','В первой версии владельцы обращаются к команде сервиса через форму сотрудничества. Личный кабинет не предусмотрен.']];
function faqBlock(indices=[0,1,2,3]){return `<div class="faq">${indices.map(i=>`<details><summary>${faqs[i][0]}</summary><p>${faqs[i][1]}</p></details>`).join('')}</div>`}
function leadForm(plan='FREE'){return `<form class="form-panel demo-form" data-form="owner"><h3>Расскажите о вашем месте</h3><p style="font-size:12px;margin:-10px 0 22px">Интересует тариф: <strong>${esc(plan)}</strong>. Все поля со звёздочкой обязательны.</p><div class="field"><label for="venue-name">Название площадки *</label><input class="input" id="venue-name" name="venue" required placeholder="Например, Оранжерея «Сад»"></div><div class="field"><label for="person-name">Ваше имя *</label><input class="input" id="person-name" name="name" autocomplete="name" required placeholder="Как к вам обращаться"></div><div class="field"><label for="phone">Телефон *</label><input class="input" id="phone" name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{7,22}" placeholder="+375 (__) ___-__-__"></div><div class="field"><label for="contact">Email или Telegram *</label><input class="input" id="contact" name="contact" required placeholder="you@example.com или @username"></div><div class="field"><label for="site">Сайт или социальные сети</label><input class="input" id="site" name="site" placeholder="https://"></div><label class="check"><input type="checkbox" required><span>Согласен с <a href="#/legal/privacy" style="text-decoration:underline">политикой обработки данных</a></span></label><button type="submit" class="btn full">Отправить заявку ${ic('arrow')}</button><small style="color:var(--muted);display:block;margin-top:13px;font-size:10px">Демонстрационная форма: данные не отправляются и не сохраняются. Для проверки используйте условные сведения.</small></form>`}
function owners(){const qp=new URLSearchParams(route().split('?')[1]||'');let p=qp.get('plan')||'FREE';if(!['FREE','PRO','TOP'].includes(p))p='FREE';return `<main><div class="container"><div class="breadcrumbs" style="padding-top:30px"><a href="#/">Главная</a> / Владельцам площадок</div><section class="owner-hero"><div><span class="eyebrow">У ВАС ЕСТЬ МЕСТО. У НИХ — ПОВОД.</span><h1>Пусть о вашем<br>пространстве<br>узнают больше.</h1><p>Красиво расскажите о площадке и помогите будущим гостям увидеть в ней место для своего события.</p><button class="btn" data-action="scroll-application">Разместить бесплатно ${ic('arrow')}</button><p style="font-size:11px;margin-top:15px">Прямые обращения · Без комиссии с аренды</p></div><div class="owner-visual">${card(venues[0])}</div></section></div><section class="section soft"><div class="container">${sectionHead('Ваше пространство — в главной роли')}<div class="benefits"><div class="benefit">${ic('camera')}<h3>Покажите характер</h3><p>Фотографии, видео и кейсы расскажут о месте лучше длинного рекламного текста.</p></div><div class="benefit">${ic('guests')}<h3>Встретьте свою аудиторию</h3><p>Площадку найдут люди, которые уже выбирают место по формату, бюджету и числу гостей.</p></div><div class="benefit">${ic('phone')}<h3>Общайтесь напрямую</h3><p>Гости позвонят или напишут вам. Вы сами обсуждаете детали и условия аренды.</p></div></div></div></section><section class="section"><div class="container">${sectionHead('От заявки — к первым знакомствам')}<div class="steps"><div><span class="step-num">01</span><h3>Оставьте заявку</h3><p>Название, ваши контакты и ссылка на площадку.</p></div><div><span class="step-num">02</span><h3>Подготовим карточку</h3><p>Соберём фотографии, описание и важные характеристики.</p></div><div><span class="step-num">03</span><h3>Встречайте обращения</h3><p>Пользователи найдут ваши контакты в карточке.</p></div></div></div></section><section class="section soft"><div class="container"><div class="grid2"><div><span class="eyebrow">КОГДА ХОЧЕТСЯ БОЛЬШЕ</span><h2>Понимайте интерес.<br>Усиливайте продвижение.</h2><p style="margin-top:23px;max-width:490px">Следите за просмотрами и переходами к контактам. Используйте PRO для подробной презентации, а TOP — для отмеченных рекламных позиций.</p></div><div><span class="badge">Пример статистики · условные данные за месяц</span><div class="stats"><div class="stat"><strong>1 240</strong><small>просмотров</small></div><div class="stat"><strong>86</strong><small>открытий контактов</small></div><div class="stat"><strong>42</strong><small>сохранения</small></div></div><p style="font-size:11px;margin-top:18px">Иллюстрация будущей аналитики, не прогноз результатов.</p></div></div></div></section><section class="section"><div class="container">${sectionHead('Начните с того, что подходит вам','','#/pricing','Сравнить тарифы')}${plans()}</div></section><section class="section"><div class="container">${sectionHead('Остались вопросы?')}${faqBlock([2,3,4,5])}</div></section><section class="section soft" id="application"><div class="container form-layout"><div><span class="eyebrow">ДАВАЙТЕ ПОЗНАКОМИМСЯ</span><h2>Ваше место<br>заслуживает внимания.</h2><p style="margin-top:22px">Заполните короткую форму — это первый шаг к размещению.</p><p style="font-size:12px;margin-top:25px">В прототипе можно проверить валидацию и успешное завершение заявки.</p></div>${leadForm(p)}</div></section></main>`}
function pricing(){return `<main class="container">${pageTop('Больше возможностей для вашего места','От бесплатной карточки до рекламного продвижения. Выберите подходящий формат.','Тарифы')}<section style="padding:15px 0 35px">${plans()}</section><section class="section">${sectionHead('Все возможности рядом')}<div class="compare-scroll"><table class="spec-table" style="min-width:650px"><thead><tr><th>Возможность</th><th>FREE</th><th>PRO</th><th>TOP</th></tr></thead><tbody>${[['Фотографии','До 5','До 30','До 30'],['Видео','—','Да','Да'],['Описание','Краткое','Подробное','Подробное'],['Контакты и характеристики','Да','Да','Да'],['Кейсы','1','До 5','До 10'],['Специальные предложения','—','Да','Да'],['Оформление карточки','Базовое','Расширенное','С выделением'],['Аналитика','Базовая','Расширенная','С рекламной статистикой'],['Рекламное продвижение','—','—','Да, с маркировкой'],['Цена за месяц','0 BYN','39 BYN','99 BYN']].map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="section">${sectionHead('Перед первым шагом')}${faqBlock([3,4,5,2])}</section><div class="owner-banner"><div><h2>Не уверены, с чего начать?</h2><p>Расскажите о площадке. Подберём формат знакомства с аудиторией.</p></div>${btn('Обсудить размещение','#/owners','peach')}</div></main>`}
function about(){return `<main class="container">${pageTop('Места объединяют.','', 'О проекте')}<div class="about-quote serif">Мы помогаем найти пространство<br>для того, что важно вам.</div><div class="wide-photo">${image('garden','Люди собираются за праздничным столом')}</div><section class="section"><div class="about-grid"><div><span class="eyebrow">ЗАЧЕМ МЫ ЗДЕСЬ</span><h2>Меньше долгих поисков.<br>Больше предвкушения.</h2><p>Найти подходящую площадку бывает сложнее, чем придумать само событие. Фотографии разбросаны по соцсетям, условия неясны, а сравнивать приходится по памяти.</p><p>EventSpace собирает места, характеристики и контакты в одном каталоге. Начинаем с Минска и планируем постепенно знакомить вас с пространствами по всей Беларуси.</p></div>${image('studio','Светлый зал для встреч')}</div></section><section class="section soft" style="padding-left:28px;padding-right:28px;border-radius:17px">${sectionHead('Простые принципы')}<div class="benefits"><div class="benefit"><h3>Свобода выбора</h3><p>Публичный каталог и контакты доступны без регистрации. Вы выбираете в своём темпе.</p></div><div class="benefit"><h3>Прямой разговор</h3><p>Пользователи и владельцы общаются напрямую. Сервис помогает познакомиться.</p></div><div class="benefit"><h3>Понятные условия</h3><p>Вместимость и цена заметны сразу. Рекламные карточки получают отдельную маркировку.</p></div></div></section><section class="section"><div class="grid2"><div><h2>Для тех, кто собирает людей</h2><p style="margin:20px 0">Сохраняйте места, сравнивайте детали и смотрите примеры событий. Всё, чтобы сделать уверенный первый шаг.</p>${btn('Найти площадку','#/catalog','outline')}</div><div><h2>Для тех, у кого есть место</h2><p style="margin:20px 0">Покажите характер пространства, поделитесь кейсами и познакомьтесь с будущими гостями.</p>${btn('Рассказать о площадке','#/owners','outline')}</div></div></section>${demo}</main>`}
function contacts(){return `<main class="container">${pageTop('Давайте поговорим','Вопрос о сервисе, идея для журнала или предложение сотрудничества — мы открыты к разговору.','Контакты')}<div class="contact-grid"><div class="contact-info"><span class="eyebrow">НАПИШИТЕ НАМ</span><h3>Общие вопросы</h3><p class="serif">hello@eventspace.example</p><h3>Партнёрство и размещение</h3><p class="serif">partners@eventspace.example</p><p>Минск, Беларусь<br>Пн–пт, 10:00–18:00 (время Минска)</p><div class="demo-note">Контакты вымышлены, письма не доставляются.</div><p style="margin-top:25px">Чтобы обсудить конкретную площадку, воспользуйтесь контактами на её странице.</p></div><form class="form-panel demo-form" data-form="feedback"><h3>Обратная связь</h3><div class="field"><label for="feedback-name">Ваше имя *</label><input class="input" id="feedback-name" name="name" required autocomplete="name" placeholder="Как к вам обращаться"></div><div class="field"><label for="feedback-email">Email *</label><input class="input" id="feedback-email" name="email" type="email" required placeholder="you@example.com"></div><div class="field"><label for="feedback-message">Сообщение *</label><textarea class="input" id="feedback-message" name="message" required placeholder="Чем можем помочь?"></textarea></div><label class="check"><input type="checkbox" required><span>Согласен с <a href="#/legal/privacy" style="text-decoration:underline">политикой обработки данных</a></span></label><button class="btn full" type="submit">Отправить сообщение ${ic('arrow')}</button><small style="font-size:10px;color:var(--muted);display:block;margin-top:14px">Демонстрационная форма. Данные не отправляются и не сохраняются.</small></form></div><section class="section">${sectionHead('Возможно, ответ уже здесь')}${faqBlock([0,1,2,4])}</section></main>`}
function notFound(){return `<main class="container">${pageTop('Кажется, мы немного заблудились','', '404')}<div class="empty"><span class="serif" style="font-size:130px;line-height:1;color:#b4bba4">404</span><h2>У этой страницы другой адрес</h2><p>Возможно, ссылка устарела. Но ваше место для события точно найдётся.</p><div class="button-row">${btn('На главную','#/')} ${btn('Открыть каталог','#/catalog','outline')}</div></div></main>`}
function states(){const tabs=[['404','Страница 404'],['no-results','Нет результатов'],['loading','Загрузка'],['error','Ошибка формы'],['success','Заявка принята'],['favorites','Пустое избранное'],['compare','Пустое сравнение']];let content='';if(stateView==='404')content=notFound().replace('<main class="container">','<div>').replace('</main>','</div>');if(stateView==='no-results')content=empty('search','Пока ни одного совпадения','Попробуйте увеличить бюджет или убрать несколько фильтров. Ваши условия можно изменить в любой момент.','Изменить фильтры',null,'#/catalog');if(stateView==='favorites')content=empty('heart','Здесь будут ваши любимые места','Нажмите на сердечко в карточке, чтобы сохранить площадку без регистрации.','Найти своё место',null,'#/catalog');if(stateView==='compare')content=empty('compare','Посмотрим на детали вместе?','Добавьте от двух до четырёх площадок из каталога. Сравним цену, вместимость и условия.','Выбрать площадки',null,'#/catalog');if(stateView==='loading')content=`<div role="status" aria-label="Площадки загружаются"><p style="margin-bottom:20px">Ищем места для вашей истории…</p><div class="grid3">${[1,2,3].map(()=>`<div class="venue-card"><div class="skeleton" style="height:230px"></div><div style="padding:22px"><div class="skeleton" style="height:24px;width:80%;margin-bottom:17px"></div><div class="skeleton" style="height:14px;width:65%;margin-bottom:25px"></div><div class="skeleton" style="height:38px"></div></div></div>`).join('')}</div></div>`;if(stateView==='error')content=`<div class="form-panel" style="max-width:570px;margin:auto"><h3>Заявка на размещение</h3><div class="form-message error-message" role="alert">Не удалось отправить заявку. Ваши данные сохранены в полях — попробуйте ещё раз.</div><div class="field"><label>Название площадки</label><input class="input" value="Оранжерея «Сад»"></div><div class="field"><label>Телефон</label><input class="input" value="+375 (00) 000-00-00"></div><button class="btn full" data-action="retry">Попробовать снова ${ic('arrow')}</button><p style="font-size:11px;margin-top:14px">Макет ошибки сети. Повторная отправка покажет успешное состояние.</p></div>`;if(stateView==='success')content=empty('check','Спасибо! Мы познакомились.','В рабочем сервисе команда свяжется с вами для подготовки карточки. В прототипе заявка никуда не отправлена.','Вернуться на главную',null,'#/');return `<main class="container">${pageTop('Состояния, о которых мы позаботились','Служебные экраны и обратная связь в едином стиле.','Состояния интерфейса')}<div class="state-list">${tabs.map(([id,t])=>`<button class="chip ${stateView===id?'active':''}" data-action="state" data-id="${id}">${t}</button>`).join('')}</div><section style="background:white;border:1px solid var(--line);border-radius:16px;padding:22px">${content}</section><p style="font-size:11px;margin-top:20px">Состояния представлены отдельно для проверки макетов. Пустая выдача, избранное и сравнение также доступны в основном сценарии.</p></main>`}
function legal(kind){const privacy=kind==='privacy';return `<main class="container"><div class="reading legal">${pageTop(privacy?'Политика конфиденциальности':'Условия использования','Шаблон юридической страницы для последующей правовой проверки.','Правовая информация')}<div class="demo-note">Демонстрационный текст · не финальный юридический документ</div><h2>1. ${privacy?'Общие положения':'О сервисе'}</h2><p>${privacy?'Этот шаблон описывает структуру будущей политики обработки персональных данных. Перед запуском сюда необходимо добавить сведения об операторе, применимые основания обработки и порядок реализации прав субъектов данных.':'EventSpace — информационная платформа для поиска площадок. Пользователи самостоятельно связываются с владельцами и согласовывают условия проведения мероприятий.'}</p><h2>2. ${privacy?'Какие сведения обрабатываются':'Использование каталога'}</h2><p>${privacy?'В рабочем сервисе формы могут обрабатывать имя, контактные данные и сведения о площадке в целях ответа на обращение. В текущем демонстрационном прототипе содержимое форм не отправляется и не сохраняется.':'Каталог, избранное и сравнение доступны без регистрации. Все площадки, цены и контакты текущего прототипа вымышлены и служат для демонстрации интерфейса.'}</p><h2>3. ${privacy?'Локальное хранение':'Рекламные материалы'}</h2><p>${privacy?'Идентификаторы избранных и сравниваемых демонстрационных площадок сохраняются локально в браузере. Вы можете очистить их в соответствующих разделах или через настройки браузера.':'Рекламные площадки отмечены меткой «TOP · Реклама». Партнёрские статьи имеют явную маркировку. Итоговые условия рекламных размещений утверждаются отдельно.'}</p><h2>4. ${privacy?'Сроки, права и обращения':'Ответственность и контакты'}</h2><p>В финальной версии здесь будут указаны реквизиты оператора, порядок обращений и применимые сроки. Демонстрационный адрес: hello@eventspace.example.</p><div style="margin-top:30px">${btn('Связаться с командой','#/contacts','outline')}</div></div></main>`}
function design(){return `<main class="container">${pageTop('Дизайн-система EventSpace','Тёплая редакционная эстетика и спокойный, предсказуемый интерфейс.','Дизайн-система')}<section class="section"><span class="eyebrow">01 / ВИЗУАЛЬНАЯ КОНЦЕПЦИЯ</span><h2>Место для важных моментов.</h2><p style="max-width:700px;margin-top:20px">Палитра природных оттенков, выразительные заголовки с засечками и крупные фотографии. Оливковый объединяет навигацию и основные действия, терракотовый выделяет редакционные детали.</p><div class="tokens">${[['Молочный','#FAF9F5','#263229'],['Оливковый','#3B4934','#fff'],['Чернильный','#263229','#fff'],['Терракота','#AD5C42','#fff'],['Шалфей','#E9ECDF','#263229']].map(([t,c,fg])=>`<div><div class="swatch" style="background:${c};color:${fg}">${t}</div><p style="font-size:11px;margin-top:7px">${c}</p></div>`).join('')}</div></section><section class="section"><span class="eyebrow">02 / ТИПОГРАФИКА И СЕТКА</span><h2>Ясно. Спокойно. Выразительно.</h2><p style="margin-top:15px">Georgia — заголовки. Arial / Helvetica — интерфейс и основной текст. Системные шрифты с полной поддержкой кириллицы.</p><div class="compare-scroll"><table class="spec-table"><thead><tr><th>Параметр</th><th>Desktop · 1440</th><th>Tablet · 768</th><th>Mobile · 390</th></tr></thead><tbody>${[['Контейнер','1280 px','720 px','354 px'],['Сетка','12 колонок','8 колонок','4 колонки'],['Поля','80 px','24 px','18 px'],['Промежутки','24 px','18–24 px','16–24 px'],['H1 / H2','64 / 42 px','52 / 35 px','43 / 32 px'],['Текст / подписи','15 / 12 px','15 / 12 px','14 / 11 px'],['Секции','72 px','72 px','45 px']].map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p style="margin-top:20px;font-size:13px">Базовый шаг отступов: 4 px. Радиусы: 8 px для полей, 12–16 px для карточек, 22 px для обложек. Основные кнопки — от 48 px в высоту.</p></section><section class="section"><span class="eyebrow">03 / ЭЛЕМЕНТЫ УПРАВЛЕНИЯ</span><h2>Одна система для всего сайта</h2><div class="component-row"><button class="btn" data-action="demo-toast">Основное действие ${ic('arrow')}</button><button class="btn light" data-action="demo-toast">Вторичное действие</button><button class="btn outline" disabled>Недоступно</button><button class="icon-btn selected" aria-label="Выбрано" data-action="demo-toast">${ic('heart')}</button><span class="badge">Новое место</span><span class="badge ad">TOP · Реклама</span></div><div class="grid3"><div class="field"><label for="ds-input">Обычное поле</label><input class="input" id="ds-input" placeholder="Введите значение"></div><div class="field"><label for="ds-select">Выпадающий список</label><select class="input" id="ds-select"><option>Минск</option><option>Минский район</option></select></div><div class="field"><label for="ds-error">Ошибка валидации</label><input class="input" id="ds-error" aria-invalid="true" aria-describedby="ds-error-text" value="Неверный адрес" style="border-color:var(--accent)"><small id="ds-error-text" style="color:var(--accent)">Введите корректный email</small></div></div><div class="component-row"><label class="check"><input type="checkbox" checked>Выбрано</label><label class="check"><input type="checkbox">Не выбрано</label><label class="check"><input type="checkbox" disabled>Недоступно</label><label class="check"><input type="checkbox" class="toggle" checked>Только различия</label><button class="chip active">Активный фильтр ${ic('close')}</button><button class="chip">Обычный фильтр</button></div><label for="ds-range">Диапазон цены</label><input class="range" id="ds-range" type="range" style="max-width:350px;display:block;margin-top:15px"><div class="component-row"><button class="btn outline" data-action="design-modal">Модальное окно</button><button class="btn outline" data-action="demo-toast">Уведомление</button><a class="btn outline" href="#/states">Пустые состояния</a></div><div class="component-row">${btn('Каталог с активными фильтрами','#/catalog?event='+encodeURIComponent('Свадьба')+'&price=200','outline')}</div><p style="font-size:13px">Наведение: более тёмная заливка / граница. Активное: изменение фона и подписи. Фокус: контрастная обводка 2 px. Неактивное: сниженная насыщенность. Ошибка: терракотовая граница и текстовая подсказка. Выбор всегда отражён и текстом.</p></section><section class="section"><span class="eyebrow">04 / КАРТОЧКИ И МЕДИА</span><div class="grid3">${card(venues[0])}${caseCard(cases[0])}${articleCard(articles[0])}</div></section><section class="section"><span class="eyebrow">05 / НАВИГАЦИЯ И АДАПТИВНОСТЬ</span><h2>Публичный сайт без лишних шагов</h2><div class="compare-scroll"><table class="spec-table"><thead><tr><th>Раздел</th><th>Переходы и адаптация</th></tr></thead><tbody><tr><td>Главная → Каталог → Площадка</td><td>Поиск переносит условия в каталог. Мобильные фильтры открываются в панели.</td></tr><tr><td>Избранное / Сравнение</td><td>Доступны из шапки и меню. Данные хранятся в браузере без аккаунта.</td></tr><tr><td>Площадка → Контакты</td><td>На desktop — боковой блок, на mobile — закреплённая нижняя панель.</td></tr><tr><td>Сравнение 2–4 площадок</td><td>Горизонтальная прокрутка, закреплённый столбец характеристик.</td></tr><tr><td>Кейсы / Журнал → Площадка</td><td>Карточки связанных площадок сохраняют путь к контактам.</td></tr><tr><td>Владельцам → Тариф → Заявка</td><td>Короткая форма. В прототипе отправка симулируется.</td></tr></tbody></table></div></section></main>`}
function tray(){return comp.length&&!['/compare'].includes(route().split('?')[0])&&!route().startsWith('/venue/')?`<aside class="compare-tray" aria-label="Выбранные площадки"><div class="tray-thumbs">${comp.map(id=>image(venue(id).photo,venue(id).name)).join('')}</div><div><strong>Выбрано: ${comp.length} из 4</strong><br><small>${comp.length<2?'Добавьте ещё одну площадку':'Сравните важные детали'}</small></div><a class="btn peach small" href="#/compare">Сравнить ${ic('arrow')}</a><button class="text-btn" data-action="clear-compare" aria-label="Очистить сравнение">${ic('close')}</button></aside>`:''}
function render(scroll=false){closeAmenity();const r=route().split('?')[0],parts=r.split('/').filter(Boolean);let body,title;
if(r==='/'){body=home();title='Место для вашего события'}else if(r==='/catalog'){body=catalog();title='Каталог площадок'}else if(parts[0]==='venue'){body=venuePage(parts[1]);title=venue(parts[1]).name}else if(r==='/compare'){body=comparePage();title='Сравнение площадок'}else if(r==='/favorites'){body=favorites();title='Избранное'}else if(r==='/cases'){body=casesPage();title='Кейсы мероприятий'}else if(parts[0]==='cases'){body=casePage(parts[1]);title='История события'}else if(r==='/journal'){body=journal();title='Журнал'}else if(parts[0]==='journal'){body=articlePage(parts[1]);title='Журнал'}else if(r==='/owners'){body=owners();title='Разместить площадку'}else if(r==='/pricing'){body=pricing();title='Тарифы'}else if(r==='/about'){body=about();title='О проекте'}else if(r==='/contacts'){body=contacts();title='Контакты'}else if(r==='/states'){body=states();title='Состояния интерфейса'}else if(r==='/design'){body=design();title='Дизайн-система'}else if(parts[0]==='legal'){body=legal(parts[1]);title='Правовая информация'}else{body=notFound();title='Страница не найдена'}
$('#app').innerHTML=header()+body+footer()+tray();document.title=title+' — EventSpace';if(scroll)window.scrollTo(0,0);
}
function closeModal(){$('#overlay').innerHTML='';document.body.style.overflow='';if(window.lastFocus&&document.contains(window.lastFocus))window.lastFocus.focus()}
function modal(html,cls=''){window.lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><div class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${cls==='gallery-modal'?'Фотогалерея':'Информация'}"><button class="icon-btn modal-close" data-action="close-modal" aria-label="Закрыть">${ic('close')}</button>${html}</div></div>`;document.body.style.overflow='hidden';$('#overlay button')?.focus()}
function gallery(){modal(`<img src="assets/${galleryImages[galleryIndex]}.jpg" alt="Фото площадки ${galleryIndex+1}"><div class="gallery-controls"><button class="icon-btn" data-action="gallery-prev" aria-label="Предыдущее фото">${ic('back')}</button><span>${galleryIndex+1} / ${galleryImages.length} · Иллюстративные фотографии</span><button class="icon-btn" data-action="gallery-next" aria-label="Следующее фото">${ic('arrow')}</button></div>`,'gallery-modal')}
function openDrawer(type){window.lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><div class="drawer ${type==='filters'?'filters-drawer':''}" role="dialog" aria-modal="true" aria-label="${type==='filters'?'Фильтры':'Меню'}"><button class="icon-btn modal-close" data-action="${type==='filters'?'close-filters':'close-modal'}" aria-label="Закрыть">${ic('close')}</button>${type==='filters'?filterPanel('-mobile'):`<a class="logo" href="#/">Event<span>Space</span></a><nav>${[['Каталог площадок','/catalog'],['Кейсы мероприятий','/cases'],['Журнал','/journal'],['Избранное','/favorites'],['Сравнение','/compare'],['Разместить площадку','/owners'],['Тарифы','/pricing'],['О проекте','/about'],['Контакты','/contacts'],['Дизайн-система','/design'],['Состояния интерфейса','/states']].map(([t,u])=>`<a href="#${u}">${t}${ic('arrow')}</a>`).join('')}</nav>`}</div></div>`;document.body.style.overflow='hidden';$('#overlay button')?.focus()}
function updateFilter(key,value){if(key==='features'){filters.features=filters.features.includes(value)?filters.features.filter(f=>f!==value):[...filters.features,value]}else{filters[key]=value}showCount=6;if($('#overlay .filters-drawer')){$('#overlay .filter-panel').outerHTML=filterPanel('-mobile')}else render()}
function resetFilters(){filters={q:'',event:'',district:'',type:'',guests:'',price:500,features:[]};showCount=6;render();if($('#overlay .filters-drawer'))$('#overlay .filter-panel').outerHTML=filterPanel('-mobile')}
function keepFocusRender(el){let id=el.id,pos=el.selectionStart;render();let next=document.getElementById(id);next?.focus();try{next?.setSelectionRange(pos,pos)}catch(e){}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a){if(e.target.dataset.backdrop){const isFilter=!!$('#overlay .filters-drawer');closeModal();if(isFilter)render()}return}const act=a.dataset.action,id=a.dataset.id;
if(act==='amenity-info'){if(amenityOpen?.trigger===a&&amenityOpen.pinned)closeAmenity();else showAmenity(a,true);return}
if(act==='favorite'){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render();toast(saved.includes(id)?'Площадка сохранена в избранное':'Площадка удалена из избранного')}
if(act==='compare'){if(comp.includes(id)){comp=comp.filter(x=>x!==id)}else{if(comp.length>=4){toast('Можно сравнить до четырёх площадок. Уберите одну из выбранных.');return}comp.push(id)}persist();render();toast(comp.includes(id)?'Площадка добавлена в сравнение':'Площадка убрана из сравнения')}
if(act==='clear-compare'){comp=[];persist();render();toast('Список сравнения очищен')}
if(act==='clear-favorites'){saved=[];persist();render();toast('Избранное очищено')}
if(act==='menu')openDrawer('menu');if(act==='filters')openDrawer('filters');if(act==='close-filters'){closeModal();render()}if(act==='close-modal')closeModal();
if(act==='reset-filters')resetFilters();if(act==='remove-filter'){filters[a.dataset.key]=a.dataset.key==='price'?500:'';render()}if(act==='remove-feature'){filters.features=filters.features.filter(f=>f!==id);render()}
if(act==='view-map'){mapView=true;render()}if(act==='view-list'){mapView=false;render()}if(act==='load-more'){showCount=venues.length;render()}
if(act==='map-preview'){const v=venue(id);$('#map-preview').innerHTML=`<div class="map-preview">${image(v.photo,v.name)}<a href="#/venue/${id}"><strong>${v.name}</strong><br>До ${v.capacity} гостей · от ${v.price} BYN / час ${ic('arrow')}</a></div>`}
if(act==='gallery'){const v=venue(id);galleryImages=galleryFor(v);galleryIndex=Number(a.dataset.index)||0;gallery()}if(act==='gallery-prev'){galleryIndex=(galleryIndex+galleryImages.length-1)%galleryImages.length;gallery()}if(act==='gallery-next'){galleryIndex=(galleryIndex+1)%galleryImages.length;gallery()}
if(act==='contact'){const v=venue(id);modal(`<span class="eyebrow">СВЯЗЬ НАПРЯМУЮ</span><h2>${v.name}</h2><p>Выберите удобный способ связи с представителем. Дату, условия и итоговую стоимость обсудите напрямую.</p><div class="contact-person"><span class="avatar">А</span><div>Анна · представитель площадки<br><small>Демонстрационный контакт</small></div></div><button class="btn full" data-action="contact-channel" data-channel="Телефон">${ic('phone')}+375 (00) 000-00-00</button><button class="btn light full" data-action="contact-channel" data-channel="Telegram" style="margin-top:10px">${ic('send')}Написать в Telegram</button><button class="btn outline full" data-action="contact-channel" data-channel="Сайт площадки" style="margin-top:10px">${ic('web')}venue.example</button><div class="demo-note" style="margin-top:20px">Контакты вымышлены. Звонки и сообщения не выполняются.</div>`)}
if(act==='contact-channel')toast(`${a.dataset.channel}: демонстрационный контакт, переход отключён`);
if(act==='case-filter'){caseFilter=id;render()}if(act==='reset-cases'){caseFilter='';caseGuests='';render()}if(act==='journal-filter'){journalFilter=id;render()}if(act==='reset-journal'){journalFilter='';journalQuery='';render()}
if(act==='state'){stateView=id;render()}if(act==='retry'){stateView='success';render()}
if(act==='demo-toast')toast('Так выглядит уведомление EventSpace');if(act==='design-modal')modal(`<span class="eyebrow">КОМПОНЕНТ / МОДАЛЬНОЕ ОКНО</span><h2>Всё важное — в фокусе</h2><p>Заголовок объясняет действие, текст помогает принять решение. Окно закрывается кнопкой, по Escape или нажатием на фон.</p><button class="btn" data-action="close-modal">Понятно ${ic('check')}</button>`);
if(act==='scroll-application')$('#application')?.scrollIntoView({behavior:'smooth'});
});
document.addEventListener('input',e=>{if(e.target.id==='catalog-query'){filters.q=e.target.value;showCount=6;keepFocusRender(e.target)}if(e.target.id==='journal-query'){journalQuery=e.target.value;keepFocusRender(e.target)}});
document.addEventListener('change',e=>{if(e.target.dataset.filter)updateFilter(e.target.dataset.filter,e.target.value);if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.id==='differences'){differences=e.target.checked;render()}if(e.target.id==='case-guests'){caseGuests=e.target.value;render()}});
document.addEventListener('submit',e=>{if(e.target.id==='home-search'){e.preventDefault();let d=new FormData(e.target);filters={...filters,event:d.get('event'),district:d.get('district'),guests:d.get('guests'),price:Number(d.get('price')),q:'',type:'',features:[]};showCount=6;location.hash='/catalog'}if(e.target.matches('.demo-form')){e.preventDefault();const f=e.target;if(f.dataset.form==='owner'){const c=f.elements.contact;const val=c.value.trim();if(!/^@\w{4,}$/.test(val)&&! /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)){c.setCustomValidity('Введите email или Telegram в формате @username');c.reportValidity();c.addEventListener('input',()=>c.setCustomValidity(''),{once:true});return}}const b=f.querySelector('[type="submit"]');b.disabled=true;b.textContent='Отправляем…';setTimeout(()=>{if(!document.contains(f))return;f.innerHTML=`<div class="empty" style="min-height:380px;padding:25px 0"><span class="empty-symbol">${ic('check')}</span><h2>${f.dataset.form==='owner'?'Спасибо! Мы познакомились.':'Спасибо за ваше сообщение.'}</h2><p>Сценарий отправки успешно завершён. Это прототип: данные не отправлены и не сохранены.</p><a class="btn outline" href="#/">На главную ${ic('arrow')}</a></div>`;f.scrollIntoView({behavior:'smooth',block:'center'})},750)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&amenityOpen){closeAmenity();return}if(!$('#overlay').innerHTML)return;if(e.key==='Escape'){const wasFilter=!!$('#overlay .filters-drawer');closeModal();if(wasFilter)render()}if(e.key==='ArrowRight'&&$('#overlay .gallery-modal')){galleryIndex=(galleryIndex+1)%galleryImages.length;gallery()}if(e.key==='ArrowLeft'&&$('#overlay .gallery-modal')){galleryIndex=(galleryIndex+galleryImages.length-1)%galleryImages.length;gallery()}if(e.key==='Tab'){const fs=[...$('#overlay').querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled);if(!fs.length)return;const first=fs[0],last=fs[fs.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function navigate(){closeModal();const r=route();if(r.startsWith('/catalog?')){const p=new URLSearchParams(r.split('?')[1]);for(const k of ['event','type','district'])if(p.has(k))filters[k]=p.get(k);if(p.has('price'))filters.price=Number(p.get('price'))||500;if(p.has('sort'))sort=p.get('sort');showCount=6}render(true);if(r.startsWith('/owners?'))requestAnimationFrame(()=>$('#application')?.scrollIntoView())}
window.addEventListener('hashchange',navigate);navigate();
